def FinitelyCodedAdmission : Prop :=
  ∃ W : FiniteMetricCode,
    ∃ hw : checkFiniteMetricCode W = true, NativeCalibrated W hw

def CheckerSoundness (verify : FiniteMetricCode → Bool) : Prop :=
  ∀ W : FiniteMetricCode, verify W = true →
    ∃ hw : checkFiniteMetricCode W = true, NativeCalibrated W hw

def GatedActualSoundness (rawCheck : FiniteMetricCode → Bool) : Prop :=
  ∀ (W : FiniteMetricCode) (hW : gatedCheck rawCheck W = true),
    NativeCalibrated W (gatedCheck_metric_positive rawCheck W hW)

def GatedActualCompleteness (rawCheck : FiniteMetricCode → Bool) : Prop :=
  _root_.RiemannHypothesis →
    ∃ W : FiniteMetricCode, gatedCheck rawCheck W = true

def FullMetricPassivityAt (H : PositiveTwoModeMetric) (s : ℂ) : Prop :=
  ∀ v : ChannelVec,
    fullMetricEnergy H (channelStep s v) ≤ fullMetricEnergy H v

def FullHypotheticalAdmission : Prop :=
  ∃ H : PositiveTwoModeMetric,
    ∀ s : ℂ, ActualNontrivialZero s → FullMetricPassivityAt H s

def HypotheticalAdmission : Prop :=
  ∃ H : PositiveDiagonalMetric,
    ∀ s : ℂ, ActualNontrivialZero s → MetricPassivityAt H s

def SoloboloShiftedAxis (s : ℂ) : Prop :=
  (shiftedCoordinate s).im = 0 ∧
  (shiftedCoordinate s).re ≤ -(1 / 4 : ℝ)

def ActualRiemannHypothesis : Prop :=
  ∀ s : ℂ, 0 < s.re → s.re < 1 →
    riemannZeta s = 0 → s.re = (1 / 2 : ℝ)

def ExistsOffLineZero : Prop :=
  ∃ s : ℂ, 0 < s.re ∧ s.re < 1 ∧
    riemannZeta s = 0 ∧ s.re ≠ (1 / 2 : ℝ)

def CheckerComplete (p : DyadicProfile) (check : WitnessCode → Bool) : Prop :=
  ∀ N : ℕ, ValidStart p N →
    ∃ w : WitnessCode, w.start = N ∧ check w = true

def SemanticallyAcceptedRatePacket (p : DyadicProfile) : Prop :=
  ∃ w : RatePacket,
    ratePacketCheck w = true ∧ RatePacketBound p w

def RatePacketBound (p : DyadicProfile) (w : RatePacket) : Prop :=
  ∀ k : ℕ, residual p (w.start + k) ≤
    (w.budget : ℝ) * (3 / 4 : ℝ) ^ k

def GeometricAdmission (p : DyadicProfile) : Prop :=
  ∃ N : ℕ, ∃ C : ℝ, 0 ≤ C ∧ ∀ k : ℕ,
    residual p (N + k) ≤ C * (3 / 4 : ℝ) ^ k

def TailQuarterRate (p : DyadicProfile) : Prop :=
  ∃ N : ℕ, ∀ n ≥ N,
    (4 : ℝ) * (p.tail n - p.tail (n + 1)) ≥ p.tail n

def COFINAL_COMPLEX_HURWITZ_FRONTIER : Prop :=
  ∀ w : FiniteWitness,
    CofinalComplexLayer w → _root_.RiemannHypothesis

def COMPLEX_HURWITZ_FRONTIER : Prop :=
  ∀ w : FiniteWitness,
    AllDepthComplexLayer w → _root_.RiemannHypothesis

def SturmXiRealization : Prop :=
  ∃ (b : ℕ → ℝ) (c : ℂ), (∀ n, 0 < b (n + 1)) ∧
    TendstoLocallyUniformly (sturmApproximant b c) ActualXi.Xi atTop

def DifferentialXiRealization : Prop :=
  ∃ (a τ : ℕ → ℝ) (c : ℂ), (∀ n, 0 < a n) ∧ (∀ n, 0 ≤ τ n) ∧
    TendstoLocallyUniformly (differentialApproximant a τ c) ActualXi.Xi atTop

def DiskExhaustion (c : ℕ → ℂ) (K : ℝ) : Prop :=
  ∀ r : ℝ, 0 < r → r < 1 →
    ∃ N : ℕ, ∀ w : ℂ, ‖w‖ ≤ r → 0 < defect c K N w

def NontrivialZero (s : ℂ) : Prop :=
  riemannZeta s = 0 ∧
    (¬ ∃ n : ℕ, s = -2 * ((n : ℂ) + 1)) ∧ s ≠ 1

def ActualOffLineExplosion : Prop :=
  ¬ _root_.RiemannHypothesis →
    ∃ a : ℝ, 0 < a ∧ ∀ C : ℝ, ∃ n : ℕ, C < centralWidder a n

def ActualXiAllDepthNonnegative : Prop :=
  ∀ (a : ℝ), 0 < a → ∀ (n : ℕ),
    0 ≤ NativeSoloboloNegativity.xiWidderMoment a n

def SubexponentialAt (W : ℝ → ℕ → ℝ) (a : ℝ) : Prop :=
  ∀ b : ℝ, 1 < b →
    ∃ C : ℝ, 0 ≤ C ∧ ∀ n : ℕ, |W a n| ≤ C * b ^ n

def CofinalMersenneCentralPositive : Prop :=
  ∀ K : ℕ, ∃ k : ℕ, K ≤ k ∧
    ∀ a : ℝ, 0 < a → 0 ≤ centralWidderMoment xiR (mersenneDepth k) a
